CREATE TABLE legal_entities(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, code text UNIQUE NOT NULL, name text NOT NULL, currency text NOT NULL);
CREATE TABLE customers(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, code text UNIQUE NOT NULL, name text NOT NULL, segment text, territory text, domain text, credit_status text NOT NULL);
CREATE TABLE suppliers(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, code text UNIQUE NOT NULL, name text NOT NULL);
CREATE TABLE warehouses(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, code text UNIQUE NOT NULL, name text NOT NULL);
CREATE TABLE products(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, sku text UNIQUE NOT NULL, name text NOT NULL, category text NOT NULL, product_line text NOT NULL, uom text NOT NULL, price numeric(18,2) NOT NULL CHECK(price>=0), cost numeric(18,2) NOT NULL CHECK(cost>=0), track_stock boolean NOT NULL, tracking text NOT NULL);
CREATE TABLE inventory(product_id bigint REFERENCES products, warehouse_id bigint REFERENCES warehouses, on_hand integer NOT NULL DEFAULT 0 CHECK(on_hand>=0), reserved integer NOT NULL DEFAULT 0 CHECK(reserved>=0 AND reserved<=on_hand), unit_cost numeric(18,4) NOT NULL DEFAULT 0 CHECK(unit_cost>=0), PRIMARY KEY(product_id,warehouse_id));
CREATE TABLE periods(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, starts_on date NOT NULL, ends_on date NOT NULL, status text NOT NULL, CHECK(ends_on>=starts_on), UNIQUE(starts_on,ends_on));
CREATE TABLE accounts(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, code text UNIQUE NOT NULL, name text NOT NULL, type text NOT NULL);
CREATE TABLE journals(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, number text UNIQUE, source_type text NOT NULL, source_id text NOT NULL, posted_on date NOT NULL, currency text NOT NULL, description text NOT NULL, reversed boolean NOT NULL DEFAULT false, UNIQUE(source_type,source_id));
CREATE TABLE journal_lines(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, journal_id bigint NOT NULL REFERENCES journals, account_id bigint NOT NULL REFERENCES accounts, debit numeric(18,2) NOT NULL DEFAULT 0 CHECK(debit>=0), credit numeric(18,2) NOT NULL DEFAULT 0 CHECK(credit>=0), CHECK((debit>0 AND credit=0) OR (credit>0 AND debit=0)));
CREATE TABLE quotes(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, number text UNIQUE, customer_id bigint NOT NULL REFERENCES customers, status text NOT NULL, currency text NOT NULL, subtotal numeric(18,2) NOT NULL, tax numeric(18,2) NOT NULL, total numeric(18,2) NOT NULL, customer_reference text, revision integer NOT NULL DEFAULT 1, approved_revision integer, expires_on date NOT NULL, tax_code text NOT NULL);
CREATE TABLE quote_lines(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, quote_id bigint NOT NULL REFERENCES quotes, product_id bigint NOT NULL REFERENCES products, quantity integer NOT NULL CHECK(quantity>0), unit_price numeric(18,2) NOT NULL, discount_pct numeric(7,2) NOT NULL CHECK(discount_pct>=0 AND discount_pct<=100), net numeric(18,2) NOT NULL, tax numeric(18,2) NOT NULL, total numeric(18,2) NOT NULL);
CREATE TABLE sales_orders(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, number text UNIQUE, quote_id bigint NOT NULL UNIQUE REFERENCES quotes, customer_id bigint NOT NULL REFERENCES customers, source_key text UNIQUE NOT NULL, status text NOT NULL, currency text NOT NULL, total numeric(18,2) NOT NULL, warehouse_id bigint REFERENCES warehouses);
CREATE TABLE sales_order_lines(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, order_id bigint NOT NULL REFERENCES sales_orders, product_id bigint NOT NULL REFERENCES products, quantity integer NOT NULL CHECK(quantity>0), reserved integer NOT NULL DEFAULT 0 CHECK(reserved>=0), shipped integer NOT NULL DEFAULT 0 CHECK(shipped>=0 AND shipped<=quantity), invoiced integer NOT NULL DEFAULT 0 CHECK(invoiced>=0 AND invoiced<=quantity), unit_price numeric(18,2) NOT NULL, discount_pct numeric(7,2) NOT NULL, tax_code text NOT NULL);
CREATE TABLE purchase_orders(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, number text UNIQUE, supplier_id bigint NOT NULL REFERENCES suppliers, warehouse_id bigint NOT NULL REFERENCES warehouses, status text NOT NULL, currency text NOT NULL, tax_code text NOT NULL, total numeric(18,2) NOT NULL);
CREATE TABLE purchase_order_lines(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, order_id bigint NOT NULL REFERENCES purchase_orders, product_id bigint NOT NULL REFERENCES products, quantity integer NOT NULL CHECK(quantity>0), received integer NOT NULL DEFAULT 0 CHECK(received>=0 AND received<=quantity), invoiced integer NOT NULL DEFAULT 0 CHECK(invoiced>=0 AND invoiced<=received), unit_cost numeric(18,2) NOT NULL CHECK(unit_cost>=0));
CREATE TABLE invoices(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, number text UNIQUE, kind text NOT NULL, status text NOT NULL, currency text NOT NULL, net numeric(18,2) NOT NULL, tax numeric(18,2) NOT NULL, total numeric(18,2) NOT NULL, paid numeric(18,2) NOT NULL DEFAULT 0 CHECK(paid>=0 AND paid<=total), order_id bigint NOT NULL, supplier_reference text, journal_id bigint REFERENCES journals, UNIQUE(kind,supplier_reference));
CREATE TABLE invoice_lines(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, invoice_id bigint NOT NULL REFERENCES invoices, order_line_id bigint NOT NULL, quantity integer NOT NULL, net numeric(18,2) NOT NULL, tax numeric(18,2) NOT NULL, deferred boolean NOT NULL DEFAULT false);
CREATE TABLE payments(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, invoice_id bigint NOT NULL REFERENCES invoices, amount numeric(18,2) NOT NULL CHECK(amount>0), reference text NOT NULL, UNIQUE(invoice_id,reference));
CREATE TABLE installed_instruments(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, serial text UNIQUE NOT NULL, product_id bigint NOT NULL REFERENCES products, customer_id bigint NOT NULL REFERENCES customers, status text NOT NULL, installed_on date NOT NULL, order_id bigint REFERENCES sales_orders);
CREATE TABLE service_contracts(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, number text UNIQUE NOT NULL, customer_id bigint NOT NULL REFERENCES customers, asset_id bigint NOT NULL REFERENCES installed_instruments, coverage_start date NOT NULL, coverage_end date NOT NULL, product_id bigint NOT NULL REFERENCES products, status text NOT NULL);
CREATE TABLE renewal_intents(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, contract_id bigint NOT NULL REFERENCES service_contracts, target_start date NOT NULL,target_end date NOT NULL,status text NOT NULL,crm_deal_id bigint, UNIQUE(contract_id,target_start));
CREATE TABLE pricing_runs(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, run_key text UNIQUE NOT NULL, status text NOT NULL, category text NOT NULL, percentage numeric(7,2) NOT NULL);
CREATE TABLE pricing_run_lines(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, run_id bigint NOT NULL REFERENCES pricing_runs, product_id bigint NOT NULL REFERENCES products, old_price numeric(18,2) NOT NULL, new_price numeric(18,2) NOT NULL, UNIQUE(run_id,product_id));
CREATE TABLE quality_issues(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, fingerprint text UNIQUE NOT NULL, type text NOT NULL, severity text NOT NULL, description text NOT NULL, status text NOT NULL);
CREATE TABLE audit_events(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,created_at timestamptz NOT NULL DEFAULT now(),actor text NOT NULL,action text NOT NULL,entity_type text NOT NULL,entity_id text NOT NULL,details text NOT NULL);
